arguments.file_text:
#:property AllowUnsafeBlocks=true

Console.WriteLine($"nint size: {nint.Size} bytes");

Span<nint> signedSpan = stackalloc nint[5];
for (int i = 0; i < signedSpan.Length; i++)
    signedSpan[i] = i * 10;

Console.WriteLine("Span<nint> via stackalloc:");
foreach (var v in signedSpan)
    Console.Write($"  {v}");
Console.WriteLine();

Span<nuint> unsignedSpan = stackalloc nuint[3];
unsignedSpan[0] = nuint.MinValue;
unsignedSpan[1] = 42;
unsignedSpan[2] = nuint.MaxValue;

Console.WriteLine("Span<nuint> via stackalloc:");
foreach (var v in unsignedSpan)
    Console.Write($"  {v}");
Console.WriteLine();

